import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
	uv,
	sub,
	mul,
	vec2,
	vec3,
	float,
	mix,
	length,
	step,
	fract,
	color,
	min,
	max,
	lessThan,
	greaterThan,
	cond,
	add
} from 'three/tsl';
import { gsap } from 'gsap';
import { createNode } from '@/primitives';
import { createText } from '@/text';

export default function createNode(config, ctx) {
	const { Group, Mesh, PlaneGeometry, BoxGeometry, CircleGeometry } = ctx.THREE;

	// Root container (position/rotation/scale are applied by adapter)
	const root = new Group();

	// -----------------------------------------------------------------
	// Panel background with radial gradient, grid, and border
	// -----------------------------------------------------------------
	const PANEL_W = 3.2;
	const PANEL_H = 2.2;

	const panelGeom = new PlaneGeometry(PANEL_W, PANEL_H);
	const uvNode = uv();

	// Centered UV coordinates (-0.5 .. 0.5)
	const centeredUV = sub(uvNode, vec2(0.5));

	// Radial gradient
	const dist = length(centeredUV);
	const maxDist = float(Math.sqrt(0.5 * 0.5 + 0.5 * 0.5));
	const radialFactor = div(dist, maxDist);
	const radColor = mix(color('#14141a'), color('#0b0b10'), radialFactor);

	// Grid (0.25‑unit pitch => 4 lines per UV unit)
	const gridScale = float(4.0);
	const gridUV = mul(uvNode, gridScale);
	const lineX = step(fract(gridUV.x), float(0.005));
	const lineY = step(fract(gridUV.y), float(0.005));
	const gridMask = max(lineX, lineY);
	const gridColor = color('#e8ecf2');
	const gridAlpha = float(0.06);
	const withGrid = mix(radColor, gridColor, mul(gridMask, gridAlpha));

	// Border (hairline 0.006 unit)
	const borderThicknessUV = float(0.006 / Math.max(PANEL_W, PANEL_H));
	const distToEdge = min(
		min(uvNode.x, sub(float(1.0), uvNode.x)),
		min(uvNode.y, sub(float(1.0), uvNode.y))
	);
	const borderMask = step(distToEdge, borderThicknessUV);
	const borderColor = color('#26262f');
	const finalColor = mix(withGrid, borderColor, borderMask);

	const panelMat = new MeshBasicNodeMaterial();
	panelMat.colorNode = finalColor;
	panelMat.transparent = true;
	panelMat.side = ctx.THREE.DoubleSide;

	const panelMesh = new Mesh(panelGeom, panelMat);
	root.add(panelMesh);

	// -----------------------------------------------------------------
	// Ghost preview (wireframe watch‑card)
	// -----------------------------------------------------------------
	const ghostGroup = new Group();
	const GHOST_W = PANEL_W * 0.35; // approx 1.12 u
	const GHOST_H = PANEL_H * 0.45; // approx 0.99 u
	ghostGroup.position.set(-PANEL_W * 0.25, 0, 0.01);

	// Wireframe outline
	const ghostOutlineGeom = new PlaneGeometry(GHOST_W, GHOST_H);
	const ghostOutlineMat = new MeshBasicNodeMaterial();
	ghostOutlineMat.colorNode = color('#e8ecf2');
	ghostOutlineMat.opacity = 0.3;
	ghostOutlineMat.transparent = true;
	ghostOutlineMat.wireframe = true;
	const ghostOutline = new Mesh(ghostOutlineGeom, ghostOutlineMat);
	ghostGroup.add(ghostOutline);

	// Ghost dial (circle)
	const dialRadius = (GHOST_W * 0.55) / 2;
	const dialGeom = new CircleGeometry(dialRadius, 32);
	const dialMat = new MeshBasicNodeMaterial();
	dialMat.colorNode = color('#e8ecf2');
	dialMat.opacity = 0.22;
	dialMat.transparent = true;
	const dialMesh = new Mesh(dialGeom, dialMat);
	dialMesh.position.set(0, 0, 0.001);
	ghostGroup.add(dialMesh);

	// Ghost text bars (two horizontal rectangles)
	const barW = GHOST_W * 0.7;
	const barH = GHOST_H * 0.06;
	const barGeom = new BoxGeometry(barW, barH, 0.001);
	const barMat = new MeshBasicNodeMaterial();
	barMat.colorNode = color('#e8ecf2');
	barMat.opacity = 0.22;
	barMat.transparent = true;

	const bar1 = new Mesh(barGeom, barMat);
	const bar2 = new Mesh(barGeom, barMat);
	bar1.position.set(0, GHOST_H * 0.2, 0.001);
	bar2.position.set(0, -GHOST_H * 0.2, 0.001);
	ghostGroup.add(bar1, bar2);

	// Collect ghost materials for breathing animation
	const ghostMats = [ghostOutlineMat, dialMat, barMat];

	// Breathing opacity animation (0.24 → 0.34 over 2.4 s, yoyo, repeat)
	const ghostOpacity = { value: 0.24 };
	const ghostTL = gsap.timeline({ repeat: -1, yoyo: true, ease: 'cubic-bezier(0.445,0.05,0.55,0.95)', duration: 2.4 });
	ghostTL.to(ghostOpacity, {
		value: 0.34,
		onUpdate: () => {
			ghostMats.forEach((m) => (m.opacity = ghostOpacity.value));
		}
	});

	root.add(ghostGroup);

	// -----------------------------------------------------------------
	// Text column (headline, body)
	// -----------------------------------------------------------------
	const textGroup = new Group();
	const padding = 0.5; // 2× base unit
	const columnX = -PANEL_W / 2 + GHOST_W + padding;
	textGroup.position.set(columnX, 0, 0.02);
	root.add(textGroup);

	// Headline
	const headline = ctx.fontAtlas.createText('Your ledger is empty.', {
		fontSize: 34,
		color: '#e8ecf2',
		align: 'left'
	});
	headline.position.set(0, PANEL_H / 2 - padding - 0.3, 0);
	textGroup.add(headline);

	// Body
	const body = ctx.fontAtlas.createText(
		'Commissioned pieces and saved references will appear here once you begin.',
		{
			fontSize: 13,
			color: '#e8ecf2',
			align: 'left'
		}
	);
	body.position.set(0, headline.position.y - 0.4, 0);
	textGroup.add(body);

	// -----------------------------------------------------------------
	// CTA button
	// -----------------------------------------------------------------
	const buttonGroup = new Group();
	const BUTTON_W = 1.5;
	const BUTTON_H = 0.36;
	const buttonY = body.position.y - 0.6;
	buttonGroup.position.set(columnX + (BUTTON_W / 2), buttonY, 0.03);
	root.add(buttonGroup);

	const buttonGeom = new PlaneGeometry(BUTTON_W, BUTTON_H);
	const uvBtn = uv();

	const gradTop = color('#ff4450');
	const gradBot = color('#c1121f');
	const btnColorNode = mix(gradTop, gradBot, uvBtn.y);

	const buttonMat = new MeshBasicNodeMaterial();
	buttonMat.colorNode = btnColorNode;
	buttonMat.transparent = true;
	buttonMat.emissive = color('#ff2a38');
	buttonMat.emissiveIntensity = 1.5;

	const buttonMesh = new Mesh(buttonGeom, buttonMat);
	buttonGroup.add(buttonMesh);

	// CTA label
	const ctaLabel = ctx.fontAtlas.createText('BROWSE THE COLLECTION', {
		fontSize: 13,
		color: '#16161d',
		align: 'center'
	});
	ctaLabel.position.set(0, 0, 0.001);
	buttonGroup.add(ctaLabel);

	// Press interaction (scale down)
	buttonGroup.userData.handlers = {
		press: () => {
			gsap.to(buttonGroup.scale, {
				x: 0.97,
				y: 0.97,
				z: 0.97,
				duration: 0.12,
				ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
			});
		},
		release: () => {
			gsap.to(buttonGroup.scale, {
				x: 1,
				y: 1,
				z: 1,
				duration: 0.12,
				ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
			});
		}
	};

	// -----------------------------------------------------------------
	// Mount fade‑up animation
	// -----------------------------------------------------------------
	const allMats = [
		panelMat,
		ghostOutlineMat,
		dialMat,
		barMat,
		buttonMat,
		...[headline, body, ctaLabel].map((t) => t.material)
	];
	// initialise transparent
	allMats.forEach((m) => {
		m.transparent = true;
		if (m.opacity === undefined) m.opacity = 0;
		m.opacity = 0;
	});
	root.position.y = 0.2;

	const mountTL = gsap.timeline();
	mountTL
		.to(
			root.position,
			{
				y: 0,
				duration: 0.5,
				ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
			},
			0
		)
		.to(
			allMats.map((m) => m.opacity),
			{
				0: 1,
				duration: 0.5,
				ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
			},
			0
		);

	// -----------------------------------------------------------------
	// Cleanup
	// -----------------------------------------------------------------
	root.userData.cleanup = () => {
		// dispose geometries & materials
		panelGeom.dispose();
		panelMat.dispose();
		ghostOutlineGeom.dispose();
		ghostOutlineMat.dispose();
		dialGeom.dispose();
		dialMat.dispose();
		barGeom.dispose();
		barMat.dispose();
		buttonGeom.dispose();
		buttonMat.dispose();
		// dispose texts (assume they expose dispose)
		[headline, body, ctaLabel].forEach((t) => {
			if (t.geometry) t.geometry.dispose?.();
			if (t.material) t.material.dispose?.();
		});
		// kill timelines
		gsap.killTweensOf(ghostOpacity);
		gsap.killTweensOf(root.position);
		gsap.killTweensOf(allMats.map((m) => m.opacity));
		ghostTL.kill();
		mountTL.kill();
	};

	return root;
}
